float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}

float pulseC(float t){float ph=fract(t*0.55);return ph<0.25?smoothstep(0.0,0.25,ph):1.0-smoothstep(0.25,1.0,ph);}

float snow(vec2 uv,float sc,float trav,float seed){vec2 g=uv*sc+vec2(seed*7.1,trav*sc);vec2 id=floor(g);vec2 f=fract(g)-0.5;float r=hash21(id+seed);if(r>0.35)return 0.0;vec2 o=vec2(hash21(id+1.7+seed),hash21(id+3.1+seed))-0.5;o*=0.7;float d=length(f-o);return smoothstep(0.08,0.0,d)*(0.4+0.6*hash21(id+9.0));}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;
 float t=iTime;
 float c=pulseC(t);
 // background
 vec3 col=mix(vec3(0.0,0.008,0.025),vec3(0.0,0.05,0.11),smoothstep(-0.6,0.7,uv.y));
 float rays=pow(max(0.0,0.5+0.5*sin(uv.x*5.0+uv.y*1.5+t*0.2)*sin(uv.x*9.0-uv.y+t*0.13)),3.0);
 col+=vec3(0.05,0.12,0.2)*rays*smoothstep(-0.2,0.6,uv.y)*0.35;
 // marine snow, moving down => jelly rising
 float trav=t*0.07+0.035*sin(t*0.55*6.2831);
 col+=vec3(0.35,0.5,0.6)*snow(uv,9.0,trav*0.6,1.0)*0.25;
 col+=vec3(0.45,0.6,0.7)*snow(uv,5.0,trav*1.0,2.0)*0.4;
 col+=vec3(0.6,0.75,0.85)*snow(uv,2.6,trav*1.6,3.0)*0.55;
 // jelly frame
 vec2 cen=vec2(0.07*sin(t*0.4),0.13+0.03*sin(t*0.31)+0.03*c);
 vec2 q=uv-cen;
 float a=0.12*sin(t*0.4+0.5);
 q=mat2(cos(a),-sin(a),sin(a),cos(a))*q;
 float w=0.25*(1.0-0.2*c);
 float h=0.19*(1.0+0.14*c);
 float glowAmt=0.75+0.65*c;
 vec3 jc=mix(vec3(0.2,0.85,1.0),vec3(0.75,0.4,1.0),0.35+0.35*c);
 vec3 jc2=vec3(1.0,0.45,0.85);
 // halo
 col+=jc*0.12*glowAmt*exp(-length(q*vec2(1.0,0.8))*4.5);
 // tentacles
 float L=0.62;
 for(int i=0;i<12;i++){
  float fi=float(i)/11.0;
  float xn=fi*2.0-1.0;
  float xs=xn*w*0.9;
  float ys=0.1*h-0.35*h*xn*xn*0.81;
  float s=ys-q.y;
  if(s>0.0&&s<L){
   float tx=xs*(1.0+0.6*s*(1.0-c))+sin(s*9.0-t*4.0+fi*6.0)*0.022*(s*2.5)+sin(t*0.4-s*2.5)*0.06*s;
   float d=abs(q.x-tx);
   float tp=1.0-s/L;
   float core=smoothstep(0.0025*tp+0.0008,0.0,d);
   float gl=0.0015/(d+0.003);
   float spark=0.6+0.4*sin(s*40.0-t*6.0+fi*3.0);
   col+=mix(jc,jc2,fi*0.5)*(core*0.7+gl*0.18*spark)*tp*glowAmt;
  }
 }
 // oral arms
 for(int i=0;i<4;i++){
  float fi=float(i);
  float xs=(fi-1.5)*0.025*(w/0.25);
  float L2=0.38;
  float s=0.06*h-q.y;
  if(s>0.0&&s<L2){
   float tx=xs+sin(s*6.0-t*2.5+fi*1.7)*0.03*s*3.0+sin(t*0.4-s*2.0)*0.03*s;
   float tp=1.0-s/L2;
   float wid=0.011*tp*(0.6+0.4*sin(s*70.0+fi))+0.002;
   float d=abs(q.x-tx);
   float fill=smoothstep(wid,wid*0.3,d);
   col+=jc2*(fill*0.35+0.002/(d+0.006)*0.12)*tp*glowAmt;
  }
 }
 // bell
 float e=length(q/vec2(w,h));
 float ed=(e-1.0)*min(w,h);
 float xn=q.x/w;
 float rim=0.1*h-0.35*h*xn*xn+0.018*h*sin(xn*28.0);
 float d=max(ed,rim-q.y);
 float inside=smoothstep(0.004,-0.004,d);
 float edge=exp(-abs(d)*70.0);
 float ang=atan(q.x,q.y+0.4*h);
 float canal=pow(abs(cos(ang*7.0)),24.0)*smoothstep(1.0,0.3,e);
 vec2 gq=q-vec2(0.0,0.3*h);
 float gon=exp(-pow((length(gq*vec2(1.0,1.6))-0.045)*60.0,2.0));
 float tex=0.18+0.6*pow(clamp(e,0.0,1.0),4.0)+0.25*canal+0.6*gon;
 vec3 bellCol=mix(jc,vec3(0.85,0.95,1.0),0.25)*tex*glowAmt;
 col=mix(col,col*0.6+bellCol,inside*0.85);
 col+=jc*edge*0.6*glowAmt;
 // rim running lights
 float rd=abs(q.y-rim);
 float lights=pow(0.5+0.5*sin(xn*30.0-t*6.0),8.0);
 col+=mix(jc2,vec3(1.0),0.3)*exp(-rd*90.0)*lights*step(abs(xn),0.98)*glowAmt*1.2;
 col+=jc*exp(-rd*50.0)*0.2*step(abs(xn),1.0)*glowAmt;
 // vignette + tonemap
 col*=1.0-0.45*dot(uv*0.9,uv*0.9);
 col=1.0-exp(-col*1.4);
 col=pow(col,vec3(0.95));
 fragColor=vec4(col,1.0);
}
